class Solution:
    def numJewelsInStones(self, jewels: str, stones: str) -> int:
        jewel_set = set(jewels)
        return sum(1 for s in stones if s in jewel_set)

class Solution {
public:
    int numJewelsInStones(string jewels, string stones) {
        unordered_set<char> jset(jewels.begin(), jewels.end());
        int count = 0;
        for (char s : stones) {
            if (jset.count(s)) count++;
        }
        return count;
    }
};

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        Set<Character> jset = new HashSet<>();
        for (char c : jewels.toCharArray()) jset.add(c);
        int count = 0;
        for (char s : stones.toCharArray()) {
            if (jset.contains(s)) count++;
        }
        return count;
    }
}

var numJewelsInStones = function(jewels, stones) {
    const jset = new Set(jewels);
    let count = 0;
    for (const s of stones) {
        if (jset.has(s)) count++;
    }
    return count;
};
